        nameof(RmpDecTmm) => new PropertyReference(Parent, nameof(SunSpecModel132.RmpIncDec_SF)),
        nameof(RmpIncTmm) => new PropertyReference(Parent, nameof(SunSpecModel132.RmpIncDec_SF)),
        _ => null
    };
}

